import {readFile,writeFile} from 'node:fs/promises';import {resolve} from 'node:path';import assert from 'node:assert/strict';import ts from 'typescript';
const root=resolve('.local/step07-review/independent-round13'),source=await readFile('apps/api/tests/studio/stored-zip.ts','utf8'),module=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2023,module:ts.ModuleKind.ESNext}}).outputText,{readStoredStandardZip}=await import('data:text/javascript;base64,'+Buffer.from(module).toString('base64'));
const good=JSON.parse(await readFile(root+'/evidence/latest-browser-archive-verification.json','utf8')).downloads,bad=JSON.parse(await readFile(root+'/evidence/latest-archive-negative-verification.json','utf8'));for(const row of good)assert.equal(Object.keys(readStoredStandardZip(await readFile(resolve(root,row.path)))).length,8);const rows=[];for(const row of bad){const bytes=await readFile(resolve(root,row.path));let error;try{readStoredStandardZip(bytes)}catch(e){error=e.message}assert(error,'Corrupt current ZIP accepted');rows.push({...row,candidateRejected:true,error});}await writeFile(root+'/evidence/current-candidate-reader-controls.json',JSON.stringify({acceptedNormal:good.length,rejectedCorrupt:bad.length,rows},null,2)+'\n');console.log(JSON.stringify({acceptedNormal:good.length,rejectedCorrupt:bad.length}));
